package com.bloodlink.repository.jdbc;
import com.bloodlink.db.Database; import com.bloodlink.model.*; import com.bloodlink.repository.BloodRequestRepository; import java.sql.*; import java.util.*;
public final class JdbcBloodRequestRepository implements BloodRequestRepository {
 public List<BloodRequest> findAll(){List<BloodRequest>x=new ArrayList<>();try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM blood_requests ORDER BY FIELD(priority,'EMERGENCY','URGENT','ROUTINE'),created_at DESC")){while(r.next())x.add(new BloodRequest(r.getInt("id"),r.getString("patient_name"),BloodGroup.from(r.getString("blood_group")),r.getInt("units"),r.getString("hospital"),r.getString("doctor"),Priority.valueOf(r.getString("priority")),r.getTimestamp("created_at").toLocalDateTime(),RequestStatus.valueOf(r.getString("status"))));}catch(SQLException e){throw new RuntimeException(e);}return x;}
 public BloodRequest save(BloodRequest r){String q="INSERT INTO blood_requests(patient_name,blood_group,units,hospital,doctor,priority,created_at,status) VALUES(?,?,?,?,?,?,?,?)";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,r.getPatientName());p.setString(2,r.getBloodGroup().toString());p.setInt(3,r.getUnits());p.setString(4,r.getHospital());p.setString(5,r.getDoctor());p.setString(6,r.getPriority().name());p.setTimestamp(7,Timestamp.valueOf(r.getCreatedAt()));p.setString(8,r.getStatus().name());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){if(k.next())r.setId(k.getInt(1));}return r;}catch(SQLException e){throw new RuntimeException(e);}}
 public void update(BloodRequest r){try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE blood_requests SET status=? WHERE id=?")){p.setString(1,r.getStatus().name());p.setInt(2,r.getId());p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
}
